<template><section class="center_view"><div class="page-head"><div><h2>操作日志</h2><p>记录后台关键业务操作，便于追溯。</p></div><el-input v-model="action" clearable placeholder="筛选操作类型" style="width:220px" @keyup.enter="load"/><el-button @click="load">查询</el-button></div><el-table :data="rows" v-loading="loading"><el-table-column prop="created_at" label="时间" width="180"/><el-table-column label="角色" width="100"><template #default="{row}">{{({users:"管理员",sheyingshi:"摄影师",yonghu:"用户"})[row.operator_type]||row.operator_type}}</template></el-table-column><el-table-column prop="operator_account" label="账号" width="150"/><el-table-column prop="action" label="操作" width="180"/><el-table-column prop="target_type" label="对象" width="120"/><el-table-column prop="detail" label="说明" min-width="260"/></el-table><el-pagination class="pager" background layout="total, prev, pager, next" :total="total" v-model:current-page="page" :page-size="20" @current-change="load"/></section></template>
<script setup>import {ref,getCurrentInstance} from 'vue';const http=getCurrentInstance().appContext.config.globalProperties.$http,rows=ref([]),total=ref(0),page=ref(1),action=ref(''),loading=ref(false);async function load(){loading.value=true;try{const r=await http.get('operation-logs',{params:{page:page.value,limit:20,action:action.value}});rows.value=r.data.data||[];total.value=r.data.total||0}finally{loading.value=false}}load()</script><style scoped>.page-head{display:flex;align-items:flex-end;gap:10px;justify-content:space-between;margin-bottom:20px}.page-head h2{margin:0 0 6px}.page-head p{margin:0;color:#909399}.pager{justify-content:center;margin-top:20px}</style>
